import {sectorAt,isTileInsideActiveMap,mapDefinition} from '../map.js';
import {P} from './palette.js';
import {oval,leaf,line,shape,star} from './shapes.js';
import {seed,clamp} from './animation.js';
const terrainCache=new WeakMap();
function tile(c,map,x,y,active,terrain){const T=map.tileSize,n=x+y*map.cols,pal=active?(P[terrain]||P.grass):P.locked;c.fillStyle=pal[(x+y)%2];c.fillRect(x*T,y*T,T,T);c.save();c.translate(x*T,y*T);if(x===0||y===0||x===map.cols-1||y===map.rows-1){c.fillStyle=map.visualTheme==='rooftop'?P.metalDark:P.dirt;c.fillRect(0,0,T,T);for(let i=0;i<3;i++)oval(c,seed(n+i)*T,seed(n+i+8)*T,2,1,map.visualTheme==='rooftop'?P.metal:P.soil,false)}else if(!active){for(let i=0;i<3;i++){const xx=8+i*11;oval(c,xx,23+seed(n+i)*6,12,12,P.dark);oval(c,xx-3,18+seed(n+i)*6,8,8,P.leaf,false)}line(c,[[3,34],[37,34]],P.bark,4);for(const xx of [6,32])shape(c,[[xx-2,38],[xx-2,23],[xx,20],[xx+3,23],[xx+3,38]],P.wood)}else{for(let i=0;i<2;i++){const xx=7+seed(n+i)*24,yy=10+seed(n+i+2)*22;line(c,[[xx-3,yy],[xx-1,yy-4],[xx,yy],[xx+3,yy-3]],P.leaf,.8)}if(terrain==='sunny'){oval(c,12,28,3,2,P.sun,false);oval(c,28,11,2,2,P.cream,false)}if(terrain==='high'){shape(c,[[2,33],[10,29],[20,32],[38,29],[38,36],[3,38]],P.dirt);line(c,[[4,32],[14,32],[22,30],[35,30]],P.cream,1.4);oval(c,29,15,5,3,P.metalDark)}if(terrain==='fortified'){oval(c,9,28,7,4,P.metalDark);oval(c,9,26,6,3,P.metal);line(c,[[22,14],[27,22],[35,25]],P.bark,2)}if(terrain==='fertile'){oval(c,20,25,14,6,P.soil,false);leaf(c,17,25,7,-.4);leaf(c,24,23,5,.6)}if(terrain==='none'&&seed(n)>.87){oval(c,14,17,2,2,P.cream,false);oval(c,16,19,2,2,P.sun,false)}if(map.visualTheme==='greenhouse'){c.globalAlpha=.17;c.fillStyle='#d9f4e8';c.fillRect(0,0,T,T);line(c,[[0,1],[T,1]],'#dff8ee',1)}if(map.visualTheme==='rooftop'){c.globalAlpha=.12;c.fillStyle='#879798';c.fillRect(0,0,T,T)}if(map.visualTheme==='backyard'&&seed(n+4)>.65)leaf(c,32,8,5,seed(n)*3,P.dark)}c.restore()}
export function drawTerrain(c,g,time){const map=mapDefinition(g.map),key=map.id+'|'+[...g.map.activeSectors].join('|');let cached=terrainCache.get(c);if(!cached||cached.key!==key){const canvas=document.createElement('canvas');canvas.width=map.cols*map.tileSize;canvas.height=map.rows*map.tileSize;const t=canvas.getContext('2d');for(let y=0;y<map.rows;y++)for(let x=0;x<map.cols;x++){const sector=sectorAt(g.map,x,y);tile(t,map,x,y,isTileInsideActiveMap(g.map,x,y),sector?.terrain||'none')}if(map.visualTheme==='greenhouse'){t.save();t.globalAlpha=.18;t.strokeStyle='#e8fff5';t.lineWidth=3;for(let x=0;x<=map.cols;x+=4){t.beginPath();t.moveTo(x*map.tileSize,0);t.lineTo(x*map.tileSize,map.rows*map.tileSize);t.stroke()}t.restore()}cached={key,canvas};terrainCache.set(c,cached)}c.drawImage(cached.canvas,0,0);if(g.map.unlockFlash>0){const s=map.sectors[g.map.lastUnlocked];if(s){const progress=1-g.map.unlockFlash/1.2;c.save();for(let y=s.tiles.y1;y<=s.tiles.y2;y++)for(let x=s.tiles.x1;x<=s.tiles.x2;x++){c.globalAlpha=clamp(1-progress*2+(x-s.tiles.x1+y-s.tiles.y1)*.05)*.55;c.fillStyle=P.light;c.fillRect(x*map.tileSize,y*map.tileSize,map.tileSize,map.tileSize)}c.restore()}}}
export function drawBase(c,g,time){const map=mapDefinition(g.map),b=map.basePosition,T=map.tileSize,x=b.centerX*T,y=b.centerY*T,ratio=g.hp/g.maxHp;c.save();c.translate(x,y);oval(c,0,24,37,11,P.shadow,false);shape(c,[[-34,18],[0,32],[34,17],[0,3]],P.soil);shape(c,[[-28,-9],[0,-21],[28,-8],[28,16],[0,29],[-28,16]],map.visualTheme==='greenhouse'?P.metal:P.wood);shape(c,[[-24,-8],[-2,1],[-2,21],[-24,12]],P.slow);shape(c,[[2,1],[24,-8],[24,12],[2,22]],P.green);shape(c,[[-34,-12],[0,-34],[34,-12],[0,3]],map.visualTheme==='rooftop'?P.metalDark:P.dark);shape(c,[[-25,-13],[0,-29],[24,-13],[0,-2]],P.slow);line(c,[[0,-29],[0,-2]],P.light,2);line(c,[[-14,-20],[14,-6]],P.light,1.5);leaf(c,0,-30,10,-.55);leaf(c,0,-30,8,.75,P.light);oval(c,0,10,8,9,P.gold);star(c,0,9,5,P.sun,time*.12);line(c,[[-29,-7],[-29,17],[0,30],[29,17],[29,-7]],P.bark,3);if(ratio<.65)line(c,[[17,-6],[11,0],[15,5],[9,10]],P.ink,1.5);if(ratio<.3){line(c,[[-19,0],[-11,6],[-15,14]],P.bark,2);leaf(c,20,23,8,1.8,P.gold)}c.restore()}
